'use strict';
(function(root){const profile=p=>root.RPG_RAID_PROFILES.find(k=>k.hero===p.hero&&k.cell===p.cell),kit=p=>p.kit||profile(p)?.kit;
function damage(s,p,power){const n=Math.min(s.boss.hp,p.attack*power*(1+(root.RPG_SUPPORT_RAID?root.RPG_SUPPORT_RAID.bonus(s,p):(p.powerUntil>s.t?p.powerBonus||0:0)))*(1+(root.RPG_SUPPORT_RAID?.value(s,{roleUnit:s.boss.roleUnit},'vulnerable')||0))*(s.boss.exposedUntil>s.t?1.65:1));s.boss.hp-=n;p.damage+=n;return n;}
function cast(s,p,slot){const spec=kit(p)?.[slot];if(spec?.supportKit)return root.RPG_SUPPORT_RAID.cast(s,p,slot);if(!spec||p.hp<=0||p.prison>0||p.cooldowns[slot]>s.t)return false;const close=Math.hypot(p.x-400,p.y-190)<=spec.range;if(!close&&['strike','dot'].includes(spec.effect))return false;if(close)damage(s,p,spec.power);for(const q of s.players.filter(q=>q.hp>0)){if(spec.heal){const n=Math.min(q.maxHP-q.hp,q.maxHP*spec.heal);q.hp+=n;p.healing+=n;if(q!==p)p.allyHealing+=n;}if(spec.shield&&q.shield<=q.maxHP*spec.shield){q.shield=q.maxHP*spec.shield;q.shieldUntil=s.t+7;q.shieldOwner=p.id;}if(spec.guard){if(spec.guardSelf){if(q===p)q.spinGuardUntil=s.t+2;}else{q.guardUntil=s.t+5;q.guardOwner=p.id;}}}if(spec.buff){p.powerUntil=s.t+spec.duration;p.powerBonus=spec.buff;}if(spec.tickPower){p.abilities=(p.abilities||[]).filter(a=>a.slot!==slot&&a.until>s.t);p.abilities.push({slot,kind:spec.effect,until:s.t+spec.duration,next:s.t+2,power:spec.tickPower});}p.cooldowns[slot]=s.t+spec.cd;p.lastCast=s.t;s.effects.push({kind:spec.effect,slot,owner:p.id,at:s.t,x:400,y:190});return true;}
function tick(s){root.RPG_SUPPORT_RAID?.tick(s);for(const p of s.players){if(p.hp<=0){p.abilities=[];continue;}if(p.shieldUntil<=s.t)p.shield=0;for(const a of p.abilities||[]){if(a.until<s.t||a.next>s.t)continue;const value=damage(s,p,a.power);a.next=s.t+2;s.effects.push({kind:'hit',owner:p.id,at:s.t,x:400,y:190,value:Math.ceil(value),source:a.kind});}p.abilities=(p.abilities||[]).filter(a=>a.until>=s.t);}}
root.RPG_RAID_COMBAT={profile,kit,cast,tick};if(typeof module!=='undefined')module.exports=root.RPG_RAID_COMBAT;
})(typeof window!=='undefined'?window:globalThis);
